import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Attribute — Detail","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-attribute-detail","title":"Attribute Detail (with translations and options)","description":"Single attribute record including all locale translations and — for select/multiselect/checkbox types — all options, each with their own locale translations.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/attributes/12\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"id=12\\n","response":"{\\n  \\"id\\": 12,\\n  \\"code\\": \\"color\\",\\n  \\"type\\": \\"select\\",\\n  \\"adminName\\": \\"Color\\",\\n  \\"isRequired\\": 0,\\n  \\"isUnique\\": 0,\\n  \\"valuePerLocale\\": 0,\\n  \\"valuePerChannel\\": 0,\\n  \\"isFilterable\\": 1,\\n  \\"isConfigurable\\": 1,\\n  \\"isVisibleOnFront\\": 1,\\n  \\"isUserDefined\\": 1,\\n  \\"swatchType\\": \\"color\\",\\n  \\"position\\": 5,\\n  \\"locale\\": \\"en\\",\\n  \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n  \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n  \\"validation\\": null,\\n  \\"defaultValue\\": null,\\n  \\"isComparable\\": 0,\\n  \\"enableWysiwyg\\": 0,\\n  \\"regex\\": null,\\n  \\"translations\\": [\\n    { \\"locale\\": \\"en\\", \\"name\\": \\"Color\\" },\\n    { \\"locale\\": \\"fr\\", \\"name\\": \\"Couleur\\" }\\n  ],\\n  \\"options\\": [\\n    {\\n      \\"id\\": 33,\\n      \\"adminName\\": \\"Red\\",\\n      \\"sortOrder\\": 1,\\n      \\"swatchValue\\": \\"#FF0000\\",\\n      \\"swatchValueUrl\\": null,\\n      \\"translations\\": [\\n        { \\"locale\\": \\"en\\", \\"label\\": \\"Red\\" },\\n        { \\"locale\\": \\"fr\\", \\"label\\": \\"Rouge\\" }\\n      ]\\n    },\\n    {\\n      \\"id\\": 34,\\n      \\"adminName\\": \\"Blue\\",\\n      \\"sortOrder\\": 2,\\n      \\"swatchValue\\": \\"#0000FF\\",\\n      \\"swatchValueUrl\\": null,\\n      \\"translations\\": [\\n        { \\"locale\\": \\"en\\", \\"label\\": \\"Blue\\" },\\n        { \\"locale\\": \\"fr\\", \\"label\\": \\"Bleu\\" }\\n      ]\\n    }\\n  ]\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"The attribute ID does not exist in the database","solution":"Verify the ID with the listing endpoint `GET /api/admin/catalog/attributes`"},{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/attributes/attributes-detail.md","filePath":"api/rest-api/admin/catalog/attributes/attributes-detail.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/attributes/attributes-detail.md"};function n(i,t,c,l,s,h){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attribute-—-detail" tabindex="-1">Catalog Attribute — Detail <a class="header-anchor" href="#catalog-attribute-—-detail" aria-label="Permalink to &quot;Catalog Attribute — Detail&quot;">​</a></h1><p>Returns a single attribute record by ID, including the <strong>full translations array</strong> (every locale present in the database) and — for <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> attribute types — all <strong>options</strong>, each with their own locale translations.</p><p>This is the read endpoint to call when an admin needs the complete metadata for an attribute — e.g. when opening the edit form in the Catalog → Attributes UI.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/attributes/{id}</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><p><code>{id}</code> must be a positive integer. Non-numeric values are rejected by a route requirement (<code>\\d+</code>) — this prevents the <code>{id}</code> segment from matching any other path under <code>/catalog/attributes/</code>.</p><h2 id="path-parameter" tabindex="-1">Path Parameter <a class="header-anchor" href="#path-parameter" aria-label="Permalink to &quot;Path Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The numeric attribute ID</td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>The response is a single JSON object (not wrapped in <code>{ data }</code>) with the following fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Attribute code (e.g. <code>color</code>, <code>size</code>)</td></tr><tr><td><code>type</code></td><td>string</td><td>Attribute type (e.g. <code>select</code>, <code>text</code>, <code>boolean</code>)</td></tr><tr><td><code>adminName</code></td><td>string</td><td>Internal admin-facing label</td></tr><tr><td><code>isRequired</code></td><td>integer</td><td><code>1</code> = required on product forms, <code>0</code> = optional</td></tr><tr><td><code>isUnique</code></td><td>integer</td><td><code>1</code> = value must be unique across products</td></tr><tr><td><code>valuePerLocale</code></td><td>integer</td><td><code>1</code> = separate value per store locale</td></tr><tr><td><code>valuePerChannel</code></td><td>integer</td><td><code>1</code> = separate value per channel</td></tr><tr><td><code>isFilterable</code></td><td>integer</td><td><code>1</code> = attribute appears in layered navigation filters</td></tr><tr><td><code>isConfigurable</code></td><td>integer</td><td><code>1</code> = used as a configurable variant axis</td></tr><tr><td><code>isVisibleOnFront</code></td><td>integer</td><td><code>1</code> = shown on the product page storefront</td></tr><tr><td><code>isUserDefined</code></td><td>integer</td><td><code>1</code> = created by an admin user (not a system attribute)</td></tr><tr><td><code>swatchType</code></td><td>string|null</td><td>Swatch rendering mode (<code>color</code>, <code>image</code>, <code>text</code>); <code>null</code> for non-swatch types</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position</td></tr><tr><td><code>locale</code></td><td>string|null</td><td>App locale used for the top-level scalar fields</td></tr><tr><td><code>createdAt</code></td><td>string|null</td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string|null</td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>validation</code></td><td>string|null</td><td>Validation rule string (e.g. <code>numeric</code>, <code>email</code>, <code>regex</code>); <code>null</code> if none</td></tr><tr><td><code>defaultValue</code></td><td>string|null</td><td>Default value for the attribute; <code>null</code> if not configured</td></tr><tr><td><code>isComparable</code></td><td>integer</td><td><code>1</code> if the attribute is shown in the storefront product-compare table, else <code>0</code></td></tr><tr><td><code>enableWysiwyg</code></td><td>integer</td><td><code>1</code> if a rich-text (WYSIWYG) editor is used for a <code>textarea</code> attribute, else <code>0</code></td></tr><tr><td><code>regex</code></td><td>string|null</td><td>Custom regular-expression pattern, used when <code>validation</code> is <code>regex</code>; <code>null</code> otherwise</td></tr><tr><td><code>translations</code></td><td>array</td><td>All locale translations (see below)</td></tr><tr><td><code>options</code></td><td>array</td><td>Attribute options for <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> types; <code>[]</code> for every other type</td></tr></tbody></table><h3 id="translations-item-shape" tabindex="-1"><code>translations[]</code> item shape <a class="header-anchor" href="#translations-item-shape" aria-label="Permalink to &quot;`translations[]` item shape&quot;">​</a></h3><p>Each entry in the <code>translations</code> array corresponds to one locale row in <code>attribute_translations</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Locale-specific attribute display name</td></tr></tbody></table><h3 id="options-item-shape" tabindex="-1"><code>options[]</code> item shape <a class="header-anchor" href="#options-item-shape" aria-label="Permalink to &quot;`options[]` item shape&quot;">​</a></h3><p>Each entry represents one attribute option (row in <code>attribute_options</code>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Option ID</td></tr><tr><td><code>adminName</code></td><td>string</td><td>Internal admin label for the option</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display sort order</td></tr><tr><td><code>swatchValue</code></td><td>string|null</td><td>Swatch value — hex color code for <code>color</code> swatches, storage path for <code>image</code> swatches, display text for <code>text</code> swatches; <code>null</code> if not a swatch type</td></tr><tr><td><code>swatchValueUrl</code></td><td>string|null</td><td>Full URL to the swatch image for <code>image</code> swatches; <code>null</code> for other swatch types or no image</td></tr><tr><td><code>translations</code></td><td>array</td><td>Locale translations for this option (see below)</td></tr></tbody></table><h3 id="options-translations-item-shape" tabindex="-1"><code>options[].translations[]</code> item shape <a class="header-anchor" href="#options-translations-item-shape" aria-label="Permalink to &quot;`options[].translations[]` item shape&quot;">​</a></h3><p>Each entry corresponds to one row in <code>attribute_option_translations</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>label</code></td><td>string|null</td><td>Locale-specific display label for the option</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing, expired, or revoked admin Bearer token</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token</td></tr><tr><td><code>404 Not Found</code></td><td>The specified <code>{id}</code> does not exist in the database</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>translations</code> contains every locale in the DB</strong>, not just the current app locale. If the store has translations for <code>en</code>, <code>fr</code>, and <code>de</code>, all three entries are returned. Fields with no content for a locale are <code>null</code>.</li><li><strong><code>options</code> is <code>[]</code> for a non-option type, not <code>null</code>.</strong> Only <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> carry options; <code>text</code>, <code>textarea</code>, <code>price</code>, <code>boolean</code>, <code>datetime</code>, <code>date</code>, <code>image</code>, and <code>file</code> all return an empty list. Test the length, not for null.</li><li><strong><code>translations</code> and <code>options</code> are plain arrays</strong>, not IRIs. Nested objects (options and their translations) are serialized inline in the response — there are no follow-up requests needed.</li><li><strong>The <code>{id}</code> route parameter must be a digit.</strong> The route carries a <code>requirements: [&#39;id&#39; =&gt; &#39;\\d+&#39;]</code> constraint — non-numeric path segments are rejected with <code>404</code> before reaching the provider.</li><li><strong><code>swatchValueUrl</code></strong> is only non-null for options of attributes with <code>swatch_type = &#39;image&#39;</code>. For <code>color</code> and <code>text</code> swatches, <code>swatchValue</code> carries the display value directly and <code>swatchValueUrl</code> is always <code>null</code>.</li><li><strong><code>validation</code></strong> holds the validation rule string stored in <code>attributes.validation</code> (e.g. <code>numeric</code>, <code>email</code>, <code>decimal</code>, <code>url</code>). <code>null</code> means no validation rule is configured for the attribute.</li><li><strong>Top-level <code>locale</code></strong> reflects the app&#39;s current default locale. It is a convenience indicator — use <code>translations</code> to get display names in other locales.</li></ul>',24)]))}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
